var DATA = {"mode": "outlets", "n": 8};
function show(k,v){console.log(k+": "+v);}
var m=DATA.mode;
if(m==="watts"){
  var max=DATA.amps*DATA.volts;
  show("Rating",DATA.amps+" A x "+DATA.volts+" V = "+max+" W");
  show("Planned load",DATA.load+" W");
  show("Headroom",(max-DATA.load)+" W");
  show("Safe",DATA.load<max?"YES":"NO - overloaded");
}else if(m==="joules"){
  show("Surge rating",DATA.j+" joules");
  show("Clamping voltage",DATA.clamp+" V");
  show("Note","higher joules = longer protection life");
}else if(m==="outlets"){
  show("Outlets",DATA.n);
  show("Control","each individually switched");
}else if(m==="switch"){
  show("Outlet",DATA.which);
  show("State",DATA.on?"ON":"OFF");
  show("Isolates","that outlet only - the rest stay live");
}else if(m==="spacing"){
  show("Outlet spacing",DATA.gap+" in");
  show("Fits","bulky wall-wart adapters side by side");
}else if(m==="cord"){
  show("Cord",DATA.len+" ft, "+DATA.awg+" AWG");
  show("Note","thicker AWG runs cooler at full load");
}else if(m==="bench"){
  console.log("Bench outlet map:");DATA.map.forEach(function(x,i){console.log("  Outlet "+(i+1)+": "+x);});
}else if(m==="vampire"){
  show("Vampire load switched off",DATA.w+" W");
  show("Saved per year",Math.round(DATA.w*24*365/1000)+" kWh");
}else if(m==="order"){
  console.log("Power-on order:");DATA.seq.forEach(function(s,i){console.log("  "+(i+1)+". "+s);});
}else if(m==="ul"){
  show("Listing","UL 1363 / ETL listed");
  show("Means","tested for the loads printed on it");
}else if(m==="daisy"){
  show("Daisy-chaining strips","NEVER - fire risk");
  show("Instead","one strip per wall outlet");
}else if(m==="mistake"){
  show("Mistake",DATA.bad);show("Instead",DATA.good);
}else if(m==="care"){
  show("Care","dust the vents, check the cord yearly");
  show("Retire","when switches feel loose or the cord is nicked");
}else if(m==="workflow"){
  console.log("Bench power workflow:");DATA.steps.forEach(function(s,i){console.log("  "+(i+1)+". "+s);});
}
